window.addEventListener('keydown',e=>{if(e.target.matches('input,select'))return;if(e.code==='Escape'||e.code==='KeyP'){if(document.querySelector('dialog[open]')&&e.code==='Escape')return;e.preventDefault();if(e.repeat)return;if(state.status==='playing')pause();else if(state.status==='paused'&&$('pause-dialog').open)resume();return;}if(state.status!=='playing')return;if(input.handles(e.code))e.preventDefault();if(!e.repeat)input.key(e.code,true);if(!e.repeat&&e.code==='KeyF')toggleTorch();if(!e.repeat&&e.code==='KeyQ')scanSonar();});
