 camera.updateMatrixWorld();torch.visible=state.flashlight;torch.intensity=state.inAir?12:65;for(const o of signalObjects){const done=state.scans.includes(o.id);o.core.visible=!done;o.light.visible=!done&&quality==='high'&&Math.hypot(camera.position.x-o.g.position.x,camera.position.y-o.g.position.y,camera.position.z-o.g.position.z)<20;o.g.position.y=o.base+Math.sin(t*1.2)*.22;o.core.rotation.y=t*.32;o.ring.rotation.z=t*.25;}
 buoy.rotation.z=Math.sin(t*.7)*.045;beaconMat.emissiveIntensity=1.5+Math.pow(Math.max(0,Math.sin(t*2)),6)*2;sonarShell.visible=state.sonar>0;if(sonarShell.visible){const age=6-state.sonar;sonarShell.scale.setScalar(1+age*16);sonarMat.opacity=Math.max(0,.16-age*.028);}
